 99→  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
100→    return "pro";
101→  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
102→    return "ultimate";
103→  return "free";
